// Normalize form fields and score the lead
const f = $json;

const fullName    = (f['Full Name']      || '').trim();
const email       = (f['Work Email']     || '').trim();
const jobTitle    = (f['Job Title']      || '').trim();
const company     = (f['Company Name']   || '').trim();
const rawWebsite  = (f['Company Website']|| '').trim();
const interest    = (f['What are you interested in?'] || '').trim();

// Normalize website - strip protocol to get clean domain
const website = rawWebsite
  .replace(/^https?:\/\//i, '')
  .replace(/\/.*$/, '')
  .trim();

// Lead scoring based on job title seniority
const titleLower = jobTitle.toLowerCase();
const hotTitles  = ['ceo','cto','coo','cfo','founder','co-founder','owner',
                    'president','vp ','vice president','chief','partner'];
const warmTitles = ['director','head of','head,','manager','lead','principal',
                    'senior manager','sr manager'];

const isHot  = hotTitles.some(function(t)  { return titleLower.includes(t); });
const isWarm = warmTitles.some(function(t) { return titleLower.includes(t); });

const score     = isHot ? 'Hot' : isWarm ? 'Warm' : 'Cold';
const scoreIcon = isHot ? 'HOT'  : isWarm ? 'WARM' : 'COLD';

const submittedAt = new Date().toISOString();
const dateOnly    = submittedAt.split('T')[0];

// Search query for news API
const searchQuery = company + ' company news';

return [{
  json: {
    fullName, email, jobTitle, company, website, interest,
    score, scoreIcon, submittedAt, dateOnly, searchQuery
  }
}];

// Validate required fields before hitting external APIs
const d = $json;

if (!d.fullName) throw new Error('Full Name is required.');
if (!d.email || !d.email.includes('@')) throw new Error('Valid work email is required. Got: ' + d.email);
if (!d.company) throw new Error('Company Name is required.');
if (!d.interest) throw new Error('Interest field is required.');

return [{ json: d }];

// Parse news API response and build research context
const newsResp = $json;
const leadCtx  = $('3. Code - Validate Required Fields').first().json;

const articles = newsResp.articles || [];

// Build a compact research brief from top 5 articles
const newsBrief = articles.slice(0, 5).map(function(a, i) {
  return (i + 1) + '. ' +
    (a.title || '').trim() + ' (' +
    (a.source?.name || 'Unknown') + ', ' +
    (a.publishedAt || '').substring(0, 10) + ')' +
    (a.description ? ' - ' + a.description.substring(0, 150).trim() : '');
}).join('\n');

const companyNewsText = newsBrief || 'No recent news found for ' + leadCtx.company + '. Use general knowledge only.';

return [{
  json: {
    ...leadCtx,
    companyNewsText,
    newsArticleCount: articles.length
  }
}];

// Parse OpenAI response safely and merge all context
const gptResp = $json;
const leadCtx = $('5. Code - Parse News and Build Research Brief').first().json;

const raw = gptResp?.choices?.[0]?.message?.content || '';
if (!raw) throw new Error('OpenAI returned empty response. Verify your OpenAI credential is connected in node 6.');

let ai = {};
try {
  const cleaned = raw.trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
  ai = JSON.parse(cleaned);
} catch(e) {
  // Graceful fallback if JSON parse fails
  ai = {
    companySize:      'Unknown',
    industry:         'Unknown',
    recentSignal:     'Unable to extract from news.',
    buyingSignals:    'None detected',
    outreachSubject:  'Following up on your enquiry, ' + leadCtx.fullName,
    outreachBody:     'Hi ' + leadCtx.fullName + ', thank you for reaching out. We would love to connect and learn more about what you are looking for. Would you be open to a quick 20-minute call this week? Best, The Sales Team'
  };
}

return [{
  json: {
    fullName:         leadCtx.fullName,
    email:            leadCtx.email,
    jobTitle:         leadCtx.jobTitle,
    company:          leadCtx.company,
    website:          leadCtx.website,
    interest:         leadCtx.interest,
    score:            leadCtx.score,
    scoreIcon:        leadCtx.scoreIcon,
    submittedAt:      leadCtx.submittedAt,
    dateOnly:         leadCtx.dateOnly,
    companyNewsText:  leadCtx.companyNewsText,
    newsArticleCount: leadCtx.newsArticleCount,
    companySize:      ai.companySize      || 'Unknown',
    industry:         ai.industry         || 'Unknown',
    recentSignal:     ai.recentSignal     || '',
    buyingSignals:    ai.buyingSignals    || 'None detected',
    outreachSubject:  ai.outreachSubject  || '',
    outreachBody:     ai.outreachBody     || ''
  }
}];
